{
 bool HasFlightDrones=>world.Player.Drones.Any(u=>u.Owner=="player"&&u.Count>0&&u.Location is "Bay" or "Space" or "Reserve" or "Abandoned");
 bool droneWasAvailable;int flightDroneScroll;readonly HashSet<string> closedDroneFolders=[];DroneUnit? flightDrag;bool flightExtend;readonly HashSet<string> selectedFlightDrones=[];
 readonly List<(Rectangle Rect,string Location,string Group)> flightFolders=[];
 void SyncFlightDroneWindow(){bool available=!world.Docked&&world.Screen==ViewMode.Space&&HasFlightDrones;if(available&&!droneWasAvailable){desktop.RemoveAll(w=>w.Kind==ViewMode.Drones);EnsureWindow(ViewMode.Drones);}if(!available&&!world.Docked)desktop.RemoveAll(w=>w.Kind==ViewMode.Drones);if(world.Docked&&droneWasAvailable)desktop.RemoveAll(w=>w.Kind==ViewMode.Drones);droneWasAvailable=available;}
 void LaunchFlightDrones(string group=""){foreach(var u in world.Player.Drones.Where(u=>u.Owner=="player"&&u.Location=="Bay"&&(group.Length==0||u.Group==group)).ToArray())world.LaunchDrone(u.Id);}
 void DrawFlightDrones(DesktopWindow w){flightFolders.Clear();var r=w.Bounds;int x=r.X+7,y=r.Y+34,width=r.Width-14;
 if(droneGroupEdit){ui.Text("Group: "+droneGroupName+" [Enter]",x,y,White,11);y+=23;}
 if(droneGroupEdit){ui.Text("Group: "+droneGroupName+" [Enter]",x,y,White,11);y+=23;}
 if(droneGroupEdit){ui.Text("Group: "+droneGroupName+" [Enter]",x,y,White,11);y+=23;}
 ui.Button(new(x,y,26,21),"...",FlightDroneMenu,"Drone settings");ui.Text($"Bandwidth {world.UsedDroneBandwidth:0}/{world.Player.Stat("droneBandwidth"):0}",x+34,y+6,Muted,10);y+=27;
 ui.Button(new(x,y,(width-8)/3,23),"Engage",()=>world.DroneCommand("Engage"),"Engage drones [F]");ui.Button(new(x+(width-8)/3+4,y,(width-8)/3,23),"Orbit",()=>world.DroneCommand("Orbit"),"Return and orbit [Shift+Alt+R]");ui.Button(new(x+2*((width-8)/3+4),y,(width-8)/3,23),"Return",()=>world.DroneCommand("Return"),"Return to drone bay [Shift+R]");y+=28;
 var rows=new List<(string Label,string Tip,Action Action,DroneUnit? Unit)>();
 foreach(string location in new[]{"Bay","Space","Abandoned"}){var units=world.Player.Drones.Where(u=>u.Owner=="player"&&u.Count>0&&u.Location==location&&(location!="Abandoned"||u.System==world.SystemId&&u.Grid==world.DroneGridIdentity)).ToArray();if(location=="Abandoned"&&units.Length==0)continue;string root="folder:"+location;rows.Add(((closedDroneFolders.Contains(root)?"> ":"v ")+(location=="Abandoned"?$"Lost drones ({units.Sum(u=>u.Count)})":location=="Bay"?$"Drones in Bay ({units.Sum(u=>u.Count)})":$"Drones in Space ({units.Sum(u=>u.Count)}/{world.Player.Stat("maxActiveDrones"):0})"),"Flight folder / "+location,()=>ToggleDroneFolder(root),null));if(closedDroneFolders.Contains(root))continue;
 foreach(var group in units.GroupBy(u=>u.Group)){string name=group.Key,key=root+":"+name;rows.Add(((closedDroneFolders.Contains(key)?"  > ":"  v ")+name+$" ({group.Sum(u=>u.Count)})","Flight group / "+location+" / "+name,()=>ToggleDroneFolder(key),null));if(closedDroneFolders.Contains(key))continue;foreach(var u in group){var unit=u;rows.Add(("    "+u.Definition.Name,"Drone unit / "+u.Id,()=>world.DroneSelection=unit.Id,u));}}}
 int capacity=Math.Max(1,(r.Bottom-y-8)/24);flightDroneScroll=Math.Clamp(flightDroneScroll,0,Math.Max(0,rows.Count-capacity));foreach(var row in rows.Skip(flightDroneScroll).Take(capacity)){var rect=new Rectangle(x,y,width,23);if(rect.Contains(mouse.ToPoint())||row.Unit!=null&&(selectedFlightDrones.Contains(row.Unit.Id)||row.Unit.Id==world.DroneSelection))ui.Box(rect,new Color(42,66,74));ui.Text(ShortSpace(row.Label,row.Unit==null?(width/7):Math.Max(10,(width-100)/7)),x+4,y+6,White,11);ui.Hits.Add(new(rect,row.Action,row.Tip));if(row.Tip.StartsWith("Flight folder / "))flightFolders.Add((rect,row.Tip[16..],""));if(row.Tip.StartsWith("Flight group / ")){var parts=row.Tip[15..].Split(" / ");flightFolders.Add((rect,parts[0],parts[1]));}if(row.Unit is {} u){var d=world.EffectiveDrone(u);float[] hp=[u.Hull/Math.Max(1,d.Hull),u.Armor/Math.Max(1,d.Armor),u.Shield/Math.Max(1,d.Shield)];for(int i=0;i<3;i++){int bx=r.Right-100+i*29;ui.Box(new(bx,y+4,26,3),new Color(125,40,40));ui.Box(new(bx,y+4,(int)(26*Math.Clamp(hp[i],0,1)),3),White);}ui.Text(u.Order=="Orbit"?"Idle":u.Order=="Return"?"Returning":u.Order,r.Right-98,y+12,u.Order=="Attack"?new Color(230,85,75):Green,9);}y+=24;}
 }
 void ToggleDroneFolder(string key){if(!closedDroneFolders.Add(key))closedDroneFolders.Remove(key);}
 void AssignFlightGroup(DroneUnit u,string group){if(world.Player.Drones.Any(v=>v.Id!=u.Id&&v.Group==group&&v.Definition.Family!=u.Definition.Family)){world.Say("A drone group must contain the same drone family.");return;}u.Group=group;}
 void FlightDroneMenu(){var hit=ui.Hits.LastOrDefault(h=>h.Owner==ViewMode.Drones.ToString()&&h.Rect.Contains(mouse.ToPoint()));spaceMenuPoint=mouse;menuPath.Clear();spaceMenuTitle="Drones";spaceMenu=[];
 var u=hit?.Tip.StartsWith("Drone unit / ")==true?world.Player.Drones.FirstOrDefault(d=>d.Id==hit.Tip[13..]):null;
 string location="",group="";if(hit?.Tip.StartsWith("Flight folder / ")==true)location=hit.Tip[16..];if(hit?.Tip.StartsWith("Flight group / ")==true){var parts=hit.Tip[15..].Split(" / ");location=parts[0];group=parts[1];}if(u!=null){location=u.Location;spaceMenuTitle=u.Definition.Name;world.DroneSelection=u.Id;spaceMenu.Add(new("Show info",()=>{ShowItemInfo(u.TypeId);}));}
 string scope=u?.Id??group;
 if(location=="Bay")spaceMenu.Add(new("Launch drones",()=>{if(u!=null)world.LaunchDrone(u.Id);else LaunchFlightDrones(group);}));
 if(location=="Space") {foreach(var cmd in new[]{("Engage target","Engage"),("Return and orbit","Orbit"),("Return to drone bay","Return"),("Abandon drones","Abandon")}){string order=cmd.Item2;spaceMenu.Add(new(cmd.Item1,()=>SendFlightOrder(order,scope)));}if(u==null||u.Definition.Packet.Total>0){spaceMenu.Add(new("Assist",Children:DroneFriendlyCommands("Assist",scope)));spaceMenu.Add(new("Guard",Children:DroneFriendlyCommands("Guard",scope)));}if(u?.Definition.Harvest==true){spaceMenu.Add(new("Mine once",()=>SendFlightOrder("MineOnce",scope)));spaceMenu.Add(new("Mine repeatedly",()=>SendFlightOrder("Engage",scope)));}if(u?.Definition.Kind=="Salvage")spaceMenu.Add(new("Salvage",()=>SendFlightOrder("Engage",scope)));}
 if(u?.Definition.Fighter==true&&u.Location=="Space"){spaceMenu.Add(new("Move to point",BeginFighterMove));for(int i=0;i<u.Definition.Abilities.Length;i++){int slot=i;spaceMenu.Add(new(u.Definition.Abilities[i].Name,()=>world.FighterAbility(u.Id,slot)));}spaceMenu.Add(new("Rearm abilities",()=>world.RearmFighter(u.Id)));}
 if(u!=null){spaceMenu.Add(new("Move drone",Children:world.Player.Drones.Select(v=>v.Group).Distinct().Select(g=>new SpaceCommand(g,()=>AssignFlightGroup(u,g))).Append(new("New group",()=>{droneGroupName="New group";droneGroupEdit=true;world.DroneSelection=u.Id;})).Append(new("Remove from group",()=>u.Group="Ungrouped")).ToList()));if(u.Location=="Abandoned"){spaceMenu.Add(new("Scoop to drone bay",()=>world.ScoopDrone(u.Id)));spaceMenu.Add(new("Scoop to cargo hold",()=>world.ScoopDroneCargo(u.Id)));}}
 if(group.Length>0)spaceMenu.Add(new("Delete group",()=>{foreach(var v in world.Player.Drones.Where(v=>v.Group==group))v.Group="Ungrouped";}));
 spaceMenu.Add(new("Settings",Children:[new(world.Player.DroneAggressive?"Passive":"Aggressive",()=>world.Player.DroneAggressive=!world.Player.DroneAggressive),new((world.Player.DroneFocusFire?"Disable":"Enable")+" focus fire",()=>world.Player.DroneFocusFire=!world.Player.DroneFocusFire)]));spaceMenu.Add(new("Reconnect to lost drones",world.ReconnectDrones));}
 List<SpaceCommand> DroneFriendlyCommands(string order,string scope)=>world.Targets.Where(t=>t.Alive&&t.Friendly&&t.DroneId.Length==0).Select(t=>new SpaceCommand(t.Name,()=>{world.SelectedId=t.Id;SendFlightOrder(order,scope);})).ToList();
 void SelectFlightDrone(string id){if(!flightExtend)selectedFlightDrones.Clear();if(flightExtend&&selectedFlightDrones.Contains(id))selectedFlightDrones.Remove(id);else selectedFlightDrones.Add(id);world.DroneSelection=id;}
 void SendFlightOrder(string order,string scope){if(selectedFlightDrones.Contains(scope)&&selectedFlightDrones.Count>1){foreach(var id in selectedFlightDrones)world.DroneCommand(order,id);}else world.DroneCommand(order,scope);}
 bool HandleFlightDroneInput(MouseState m,KeyboardState keys){var top=WindowAt(mouse);if(top?.Kind==ViewMode.Drones&&m.ScrollWheelValue!=oldMouse.ScrollWheelValue){flightDroneScroll=Math.Max(0,flightDroneScroll-(m.ScrollWheelValue-oldMouse.ScrollWheelValue)/120);return true;}bool down=m.LeftButton==ButtonState.Pressed&&oldMouse.LeftButton==ButtonState.Released,up=m.LeftButton==ButtonState.Released&&oldMouse.LeftButton==ButtonState.Pressed;
 if(flightDrag!=null){if(up){var u=flightDrag;var folder=flightFolders.LastOrDefault(f=>f.Rect.Contains(mouse.ToPoint()));if(Vector2.Distance(mouse,gestureOrigin)>6&&folder.Rect.Width>0){if(folder.Group.Length>0)AssignFlightGroup(u,folder.Group);if(folder.Location=="Space"&&u.Location=="Bay")world.LaunchDrone(u.Id);if(folder.Location=="Bay"&&u.Location=="Space")world.DroneCommand("Return",u.Id);}else SelectFlightDrone(u.Id);flightDrag=null;}return true;}
 if(down&&top?.Kind==ViewMode.Drones){var h=ui.Hits.LastOrDefault(h=>h.Owner==top.Owner&&h.Tip.StartsWith("Drone unit / ")&&h.Rect.Contains(mouse.ToPoint()));if(h!=null){flightDrag=world.Player.Drones.First(u=>u.Id==h.Tip[13..]);flightExtend=keys.IsKeyDown(Keys.LeftControl)||keys.IsKeyDown(Keys.RightControl)||keys.IsKeyDown(Keys.LeftShift)||keys.IsKeyDown(Keys.RightShift);gestureOrigin=mouse;return true;}}return false;}
 List<SpaceCommand> JumpShipCommands(){if(world.Docked||world.Player.Stat("canJump")<=0)return [];var commands=new List<SpaceCommand>();List<SpaceCommand> Destinations(bool bridge,bool conduit)=>world.JumpBeacons.Where(b=>b.Left>0&&b.Hull>0&&b.System!=world.SystemId&&world.BeaconCompatibility(b,bridge?world.Player.Special.FirstOrDefault(s=>s.Definition?.Portal==true)?.Definition?.Kind??"Jump":"Jump").Length==0&&DemoWorld.BeaconDistance(world.SystemId,b.System)<=world.Player.Stat("jumpDriveRange")).Select(b=>new SpaceCommand((DemoWorld.Systems.FirstOrDefault(s=>s.Id==b.System)?.Name??b.System)+$" / {DemoWorld.BeaconDistance(world.SystemId,b.System):0.00} LY",()=>{world.JumpBeaconSelection=b.Id;if(bridge){var portal=world.Player.Special.FirstOrDefault(s=>s.Definition?.Portal==true);if(portal!=null&&!portal.Active)world.ToggleSpecial(Array.IndexOf(world.Player.Special,portal));world.BridgeSpecial(conduit);}else world.JumpToBeacon(b.System);})).ToList();commands.Add(new("Jump to",Children:Destinations(false,false)));if(world.Player.Special.Any(s=>s.Definition?.Portal==true)){commands.Add(new("Bridge to",Children:Destinations(true,false)));if(world.Player.Stat("enablePerformConduitJump")>0)commands.Add(new("Conduit jump to",Children:Destinations(true,true)));}return commands;}
